const data = $json;

const previousEvent = data.previous_event ?? null;
const previousSeverity = data.previous_severity ?? null;
const previousStatus = data.previous_status ?? null;

let shouldNotify = false;
let reason = 'no_change';

// ==================================================
// 1. PRIMEIRO INCIDENTE
// ==================================================

if (
  previousEvent === null &&
  data.should_emit === true
) {
  shouldNotify = true;
  reason = 'first_incident';
}

// ==================================================
// 2. RECUPERAÇÃO
// ==================================================

if (
  data.event === 'storage_healthy' &&
  previousEvent !== null &&
  previousStatus !== 'healthy'
) {
  return [
    {
      json: {
        ...data,

        should_emit: true,

        severity: 'info',
        event: 'storage_recovered',
        status: 'healthy',

        message:
          `O storage principal do OMEAB voltou a operar normalmente. ` +
          `O incidente anterior era: ${previousEvent}.`,

        requires_attention: false,

        suggested_action:
          'Nenhuma ação imediata necessária. Continuar monitorando a estabilidade do storage.',

        notification: {
          should_notify: true,
          reason: 'recovered',
          previous_event: previousEvent,
          previous_severity: previousSeverity,
          previous_status: previousStatus
        }
      }
    }
  ];
}

// ==================================================
// 3. NOVO TIPO DE INCIDENTE
// ==================================================

if (
  data.should_emit === true &&
  previousEvent !== null &&
  data.event !== previousEvent
) {
  shouldNotify = true;
  reason = 'incident_changed';
}

// ==================================================
// 4. ESCALADA DE SEVERIDADE
// ==================================================

if (
  data.should_emit === true &&
  previousEvent !== null &&
  data.event === previousEvent
) {

  const severityRank = {
    info: 1,
    warning: 2,
    error: 3,
    critical: 4
  };

  const currentRank =
    severityRank[data.severity] ?? 0;

  const previousRank =
    severityRank[previousSeverity] ?? 0;

  if (currentRank > previousRank) {
    shouldNotify = true;
    reason = 'severity_escalated';
  }
}

// ==================================================
// RESULTADO
// ==================================================

return [
  {
    json: {
      ...data,

      notification: {
        should_notify: shouldNotify,
        reason,

        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus
      }
    }
  }
];

const s = $json;

const errors = s.kernel_errors ?? {};

const ioErrors = Number(errors.io_error ?? 0);
const ext4Errors = Number(errors.ext4_error ?? 0);
const bufferErrors = Number(errors.buffer_io_error ?? 0);
const usbDisconnects = Number(errors.usb_disconnect ?? 0);
const usbResets = Number(errors.usb_reset ?? 0);
const remountRO = Number(errors.remount_read_only ?? 0);

let severity = 'info';
let event = 'storage_healthy';
let message = 'O storage principal do OMEAB está operando normalmente.';
let requiresAttention = false;
let suggestedAction = null;
let shouldEmit = false;

// --------------------------------------------------
// CRITICAL
// --------------------------------------------------

if (!s.device_present) {
  severity = 'critical';
  event = 'storage_device_missing';
  message = 'O dispositivo principal de storage /dev/sda não foi encontrado.';
  requiresAttention = true;
  shouldEmit = true;
  suggestedAction =
    'Verificar alimentação, conexão USB e estado do enclosure ACASIS antes de qualquer ação no filesystem.';
}

else if (!s.mounted) {
  severity = 'critical';
  event = 'storage_not_mounted';
  message = 'O storage principal não está montado em /srv/storage.';
  requiresAttention = true;
  shouldEmit = true;
  suggestedAction =
    'Verificar o dispositivo e os logs do kernel. Não executar montagem forçada ou fsck automaticamente.';
}

else if (
  s.mode === 'ro' ||
  s.emergency_ro === true
) {
  severity = 'critical';
  event = 'filesystem_read_only';
  message =
    'O filesystem principal entrou em modo somente leitura (read-only).';
  requiresAttention = true;
  shouldEmit = true;
  suggestedAction =
    'Investigar os erros de I/O e EXT4 antes de reiniciar, remontar ou executar fsck.';
}

else if (s.read_test === false) {
  severity = 'critical';
  event = 'storage_read_failure';
  message =
    'O Health Agent não conseguiu realizar uma leitura simples em /srv/storage.';
  requiresAttention = true;
  shouldEmit = true;
  suggestedAction =
    'Investigar imediatamente logs do kernel, conexão USB e integridade do dispositivo.';
}

else if (
  ioErrors > 0 ||
  ext4Errors > 0 ||
  bufferErrors > 0 ||
  remountRO > 0
) {
  severity = 'critical';
  event = 'storage_io_errors';
  message =
    `Foram detectados erros recentes no storage: ` +
    `I/O=${ioErrors}, EXT4=${ext4Errors}, ` +
    `Buffer I/O=${bufferErrors}, Remount RO=${remountRO}.`;
  requiresAttention = true;
  shouldEmit = true;
  suggestedAction =
    'Investigar os logs do kernel e a estabilidade física do storage antes de qualquer reparo.';
}

// --------------------------------------------------
// WARNING
// --------------------------------------------------

else if (usbDisconnects > 0) {
  severity = 'warning';
  event = 'storage_usb_disconnect';
  message =
    `Foram detectados ${usbDisconnects} eventos recentes de desconexão USB do storage.`;
  requiresAttention = true;
  shouldEmit = true;
  suggestedAction =
    'Verificar alimentação, cabo USB e estabilidade do enclosure.';
}

else if (usbResets > 0) {
  severity = 'warning';
  event = 'storage_usb_reset';
  message =
    `Foram detectados ${usbResets} resets USB recentes relacionados ao storage.`;
  requiresAttention = false;
  shouldEmit = true;
  suggestedAction =
    'Acompanhar a estabilidade da conexão USB e verificar se os resets continuam ocorrendo.';
}

// --------------------------------------------------
// HEALTHY
// --------------------------------------------------

else if (s.healthy === true) {
  severity = 'info';
  event = 'storage_healthy';
  shouldEmit = false;
}

// --------------------------------------------------
// EVENTO NORMALIZADO
// --------------------------------------------------

return [
  {
    json: {
      should_emit: shouldEmit,

      source: 'storage_guardian',
      severity,
      component: 'storage',
      event,
      status: s.healthy ? 'healthy' : 'active',

      timestamp:
        s.checked_at ?? new Date().toISOString(),

      message,

      details: {
        device_present: s.device_present,
        mounted: s.mounted,
        device: s.device,
        mountpoint: s.mountpoint,
        filesystem: s.filesystem,
        mount_options: s.mount_options,
        mode: s.mode,

        emergency_ro: s.emergency_ro,
        read_test: s.read_test,

        total_bytes: s.total_bytes,
        used_bytes: s.used_bytes,
        available_bytes: s.available_bytes,
        used_percent: s.used_percent,
        inode_percent: s.inode_percent,

        kernel_errors: s.kernel_errors,
        recent_errors: s.recent_errors
      },

      requires_attention: requiresAttention,
      suggested_action: suggestedAction
    }
  }
];

